// SellerProspectAdminServiceHandler is an implementation of the
// hawkr.admin.seller.v1alpha1.SellerProspectAdminService service.
type SellerProspectAdminServiceHandler interface {
	// ListProspects 是業者清單，新到舊（依 update_time）。清單的業者不帶 contacts 與 category_ids（GetProspect 才有）。
	ListProspects(context.Context, *connect.Request[v1alpha1.ListProspectsRequest]) (*connect.Response[v1alpha1.ListProspectsResponse], error)
	// CreateProspect 建立業者。display_name 與 vendor_type 必填；outreach_status 沒填是 NOT_CONTACTED，不能是 CONVERTED。
	// 統編已經被別的未封存業者持有回 already_exists（PROSPECT_TAX_ID_HELD，metadata 的 prospectIds 是持有者的 ID）；聯絡方式的比對鍵與其他未封存業者相同、而且沒有
	// 標記為不是同一家時回 failed_precondition（PROSPECT_MATCH_FOUND），confirmed_distinct_prospect_ids 涵蓋全部相符的業者
	// 才建立。建立時不能帶 logo_upload、cover_upload（建立後以 UpdateProspect 換圖）。沒有冪等鍵：重送時，統編或有識別力的聯絡方式
	// 會撞到第一筆（already_exists 或 PROSPECT_MATCH_FOUND）。
	CreateProspect(context.Context, *connect.Request[v1alpha1.CreateProspectRequest]) (*connect.Response[v1alpha1.CreateProspectResponse], error)
	// PreviewProspect 建立之前的比對，不寫入：回傳可能是同一家的業者與命中的層級（統編相同的會讓建立被拒絕，聯絡方式的
	// 比對鍵相同的需要確認不是同一家，名稱相同只供人判斷）。
	PreviewProspect(context.Context, *connect.Request[v1alpha1.PreviewProspectRequest]) (*connect.Response[v1alpha1.PreviewProspectResponse], error)
	// GetProspect 讀一個業者（任何狀態），含 contacts 與 category_ids。
	GetProspect(context.Context, *connect.Request[v1alpha1.GetProspectRequest]) (*connect.Response[v1alpha1.GetProspectResponse], error)
	// UpdateProspect 依 update_mask 部分更新；沒帶 mask 時視為列出所有非零值的欄位，要清空的欄位必須列出來。可以列的是
	// display_name、vendor_type、outreach_status（不能設成 CONVERTED）、tax_id、contacts、category、region、product_summary、
	// positioning、research_summary、priority_letter、priority_stars、category_ids、logo_upload、cover_upload；其他欄位是
	// OUTPUT_ONLY。mask 選到卻沒有值的欄位是清掉（contacts 與 category_ids 是清空）；contacts 與 category_ids 整批替換。
	// 只有進行中的業者可以改；etag 必填，與目前的版本不符回 aborted（VERSION_CONFLICT），什麼都不寫。沒有任何欄位改變時
	// 不寫入、etag 不變。
	// 換圖：logo_upload、cover_upload 帶上傳後的 staged token 與選填、只收 https 的來源網址（只作稽核，後端不會去取）；列進
	// mask 才換，沒列就沿用目前的圖。文字、聯絡方式與圖片在同一個版本條件的寫入裡，被拒絕的請求不消耗 staged token。
	// 改到聯絡方式時的比對與 confirmed_distinct_prospect_ids 同 CreateProspect；統編被別的未封存業者持有回
	// failed_precondition（PROSPECT_TAX_ID_HELD，metadata 的 prospectIds 是持有者的 ID）：持有者是進行中的，該做的是合併；
	// 持有者是已入駐的，是同一家的話請封存這筆。
	// update_mask 的 "*" 選到所有可寫的欄位，包含 logo_upload、cover_upload 與 outreach_status：它們都必須有值（上傳要帶
	// staged_token，圖片沒有清除的操作；outreach_status 不能是 UNSPECIFIED），沒有就回 invalid_argument。只改部分欄位時列出
	// 那些欄位。
	UpdateProspect(context.Context, *connect.Request[v1alpha1.UpdateProspectRequest]) (*connect.Response[v1alpha1.UpdateProspectResponse], error)
	// ArchiveProspect 封存業者（之後可還原）。etag 必填。etag 不符（包含封存已經生效後再帶舊 etag 送一次）回 aborted（VERSION_CONFLICT），不寫入；
	// 已經封存而且帶目前 etag 的回傳目前的業者；已轉成店家的回 failed_precondition。封存會釋放圖片。
	ArchiveProspect(context.Context, *connect.Request[v1alpha1.ArchiveProspectRequest]) (*connect.Response[v1alpha1.ArchiveProspectResponse], error)
	// RestoreProspect 還原封存的業者，不帶 etag（依據的是封存這個狀態）。被合併的業者不能還原；封存期間統編被別家拿走回
	// failed_precondition（PROSPECT_TAX_ID_HELD，metadata 的 prospectIds 是持有者的 ID；是同一家的話不需要還原）；聯絡方式的比對鍵被其他未封存業者佔走、而且沒有標記為不是同一家時回 failed_precondition
	// （PROSPECT_MATCH_FOUND），confirmed_distinct_prospect_ids 涵蓋全部相符的業者才還原。封存時釋放的圖片不會回來。
	RestoreProspect(context.Context, *connect.Request[v1alpha1.RestoreProspectRequest]) (*connect.Response[v1alpha1.RestoreProspectResponse], error)
	// MergeProspects 把 loser 併進 winner，回傳 winner。兩邊的 etag 都必填；兩邊都必須是進行中的業者。loser 的聯絡方式併入
	// winner、「不是同一家」的配對與分類改掛 winner、統編在 winner 沒有時搬過去；loser 的詢價連結改由 winner 承接；loser 與
	// winner 之間的「不是同一家」標記撤銷；loser 封存且不能還原，圖片釋放（不搬給 winner）。任一邊的 etag 不符（包含合併已經生效後再帶舊 etag 送一次）回 aborted（VERSION_CONFLICT），不寫入。不可逆。
	MergeProspects(context.Context, *connect.Request[v1alpha1.MergeProspectsRequest]) (*connect.Response[v1alpha1.MergeProspectsResponse], error)
	// ConvertProspect 把業者手動轉成目前的店家，進度同時變成 CONVERTED。etag 必填。店家必須是目前的（沒有關閉）；只有進行中的
	// 業者可以轉，轉過、封存與被合併的回 failed_precondition；店家已被別的業者認領回 already_exists。etag 不符（包含轉換已經生效後再帶舊 etag
	// 送一次）回 aborted（VERSION_CONFLICT），不寫入。不撤銷 vendor portal 的邀請。
	ConvertProspect(context.Context, *connect.Request[v1alpha1.ConvertProspectRequest]) (*connect.Response[v1alpha1.ConvertProspectResponse], error)
	// ListProspectDuplicates 是疑似重複的清單：進行中的業者之間比對鍵相同或名稱相同、而且沒有標記為不是同一家的配對
	// （ID 小的在 left）。keyset 分頁；永不自動合併，處理方式是 MergeProspects，或帶 confirmed_distinct_prospect_ids 的修改。
	ListProspectDuplicates(context.Context, *connect.Request[v1alpha1.ListProspectDuplicatesRequest]) (*connect.Response[v1alpha1.ListProspectDuplicatesResponse], error)
	// MarkProspectsDistinct 標記一對業者不是同一家：疑似重複清單的另一種處理方式（另一個是 MergeProspects）。標記之後這一對不再出現在
	// ListProspectDuplicates，也不再讓建立、修改與還原回 PROSPECT_MATCH_FOUND。決定的是身分、不是內容，所以不帶 etag：業者
	// 的內容之後怎麼改，這個決定都不變。兩個 ID 不可相同（invalid_argument）；兩個都必須存在（not_found）而且是進行中的業者
	// （failed_precondition，疑似重複清單只列進行中的業者之間）。已經標記過的重送回傳成功，不改寫第一次的管理員與時間（冪等）。
	// 這是商家名單的資源，不是業者的欄位：沒有清除標記的方法（明確合併一對標記過的業者會撤銷那個標記）。
	MarkProspectsDistinct(context.Context, *connect.Request[v1alpha1.MarkProspectsDistinctRequest]) (*connect.Response[v1alpha1.MarkProspectsDistinctResponse], error)
	// ListProspectTaxIDMatches 是統編對帳：業者的統編對得上目前店家的 KYC 申請、但還沒有連起來的配對（已被其他業者認領的店家
	// 不列）。處理方式是 ConvertProspect。
	ListProspectTaxIDMatches(context.Context, *connect.Request[v1alpha1.ListProspectTaxIDMatchesRequest]) (*connect.Response[v1alpha1.ListProspectTaxIDMatchesResponse], error)
}

